// Analyze all repositories and create summary
const items = $input.all();
const now = new Date();

let allRepos = [];
let problemRepos = [];
let healthyRepos = [];

items.forEach(item => {
  const repo = item.json;
  const repoName = repo.name;

  let healthScore = 100;
  let problems = [];
  let warnings = [];

  // Check last update
  const lastUpdate = new Date(repo.updated_at);
  const daysSinceUpdate = (now - lastUpdate) / (1000 * 60 * 60 * 24);

  if (daysSinceUpdate > 60) {
    healthScore -= 30;
    problems.push(`No updates in ${Math.floor(daysSinceUpdate)} days`);
  } else if (daysSinceUpdate > 30) {
    healthScore -= 15;
    warnings.push(`Last update ${Math.floor(daysSinceUpdate)} days ago`);
  }

  // Check open issues
  if (repo.open_issues_count > 20) {
    healthScore -= 25;
    problems.push(`High open issues: ${repo.open_issues_count}`);
  } else if (repo.open_issues_count > 10) {
    healthScore -= 10;
    warnings.push(`Moderate open issues: ${repo.open_issues_count}`);
  }

  // Check description
  if (!repo.description || repo.description.length < 10) {
    healthScore -= 5;
    warnings.push('Missing or minimal description');
  }

  // Determine status
  let status = 'healthy';
  if (healthScore < 50) {
    status = 'critical';
  } else if (healthScore < 75) {
    status = 'warning';
  }

  const repoData = {
    repository: repoName,
    health_score: healthScore,
    status: status,
    problems: problems,
    warnings: warnings,
    stats: {
      stars: repo.stargazers_count,
      forks: repo.forks_count,
      open_issues: repo.open_issues_count,
      language: repo.language,
      days_since_update: Math.floor(daysSinceUpdate)
    },
    repo_url: repo.html_url
  };

  allRepos.push(repoData);

  if (status !== 'healthy') {
    problemRepos.push(repoData);
  } else {
    healthyRepos.push(repoData);
  }
});

// Create summary for Claude
const claudeContext = `AI-Whisperers GitHub Organization Health Report

Total Repositories: ${allRepos.length}
Healthy: ${healthyRepos.length}
Need Attention: ${problemRepos.length}

---

REPOSITORIES NEEDING ATTENTION:

${problemRepos.map((r, idx) => {
  return `${idx + 1}. ${r.repository}
   Health Score: ${r.health_score}/100
   Status: ${r.status.toUpperCase()}
   Problems: ${r.problems.join(', ') || 'None'}
   Warnings: ${r.warnings.join(', ') || 'None'}
   Stats: ${r.stats.open_issues} issues, ${r.stats.days_since_update} days since update
   URL: ${r.repo_url}`;
}).join('\n\n')}

---

HEALTHY REPOSITORIES:
${healthyRepos.map(r => `- ${r.repository} (${r.health_score}/100)`).join('\n')}`;

return {
  json: {
    total_repos: allRepos.length,
    healthy_count: healthyRepos.length,
    problem_count: problemRepos.length,
    all_repos: allRepos,
    problem_repos: problemRepos,
    healthy_repos: healthyRepos,
    claude_context: claudeContext,
    timestamp: now.toISOString(),
    needs_analysis: problemRepos.length > 0
  }
};

// Format Claude's response for email
const claudeResponse = $input.first().json;
const summaryData = $('Analyze All Repositories').first().json;

return {
  json: {
    total_repos: summaryData.total_repos,
    healthy_count: summaryData.healthy_count,
    problem_count: summaryData.problem_count,
    problem_repos: summaryData.problem_repos,
    healthy_repos: summaryData.healthy_repos,
    claude_analysis: claudeResponse.content[0].text,
    timestamp: summaryData.timestamp
  }
};

