=<!DOCTYPE html>
<html>
<head>
<style>
  body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; line-height: 1.6; color: #333; margin: 0; padding: 0; background: #f5f5f5; }
  .container { max-width: 650px; margin: 20px auto; background: white; border-radius: 8px; overflow: hidden; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
  .header { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); color: white; padding: 30px 20px; text-align: center; }
  .header h1 { margin: 0 0 10px 0; font-size: 28px; font-weight: 600; }
  .header p { margin: 0; opacity: 0.9; font-size: 14px; }
  .summary { display: flex; justify-content: space-around; padding: 20px; background: #f8f9fa; border-bottom: 2px solid #e9ecef; }
  .summary-item { text-align: center; }
  .summary-number { font-size: 36px; font-weight: bold; margin: 0; }
  .summary-number.healthy { color: #28a745; }
  .summary-number.problems { color: #dc3545; }
  .summary-number.total { color: #667eea; }
  .summary-label { font-size: 12px; color: #666; text-transform: uppercase; margin-top: 5px; }
  .content { padding: 30px; }
  .section { margin: 20px 0; }
  .section-title { color: #667eea; font-size: 18px; font-weight: 600; margin-bottom: 15px; border-bottom: 2px solid #667eea; padding-bottom: 5px; }
  .repo-list { list-style: none; padding: 0; }
  .repo-item { background: #f8f9fa; padding: 15px; margin: 10px 0; border-radius: 6px; border-left: 4px solid #667eea; }
  .repo-item.warning { border-left-color: #ffc107; background: #fff9e6; }
  .repo-item.critical { border-left-color: #dc3545; background: #ffe6e6; }
  .repo-name { font-weight: bold; font-size: 16px; margin-bottom: 8px; }
  .repo-score { display: inline-block; padding: 3px 12px; border-radius: 12px; font-size: 13px; font-weight: bold; margin-left: 10px; }
  .score-healthy { background: #d4edda; color: #155724; }
  .score-warning { background: #fff3cd; color: #856404; }
  .score-critical { background: #f8d7da; color: #721c24; }
  .repo-details { font-size: 13px; color: #666; margin: 5px 0; }
  .problem-list { margin: 10px 0 0 0; padding-left: 20px; color: #dc3545; font-size: 14px; }
  .claude-box { background: #e8f5e9; border: 2px solid #4caf50; border-radius: 8px; padding: 20px; margin: 20px 0; }
  .claude-box h3 { color: #2e7d32; margin: 0 0 15px 0; font-size: 20px; }
  .claude-content { white-space: pre-wrap; font-family: 'Courier New', monospace; font-size: 13px; line-height: 1.8; color: #1b5e20; }
  .footer { background: #f8f9fa; padding: 20px; text-align: center; color: #666; font-size: 12px; border-top: 1px solid #e9ecef; }
  .btn { display: inline-block; padding: 10px 20px; background: #667eea; color: white; text-decoration: none; border-radius: 5px; margin: 5px; font-size: 14px; }
  .btn:hover { background: #5568d3; }
</style>
</head>
<body>
<div class="container">
  <div class="header">
    <h1>🤖 Terry Health Report</h1>
    <p>AI-Whisperers GitHub Organization</p>
  </div>

  <div class="summary">
    <div class="summary-item">
      <div class="summary-number total">{{ $json.total_repos }}</div>
      <div class="summary-label">Total Repos</div>
    </div>
    <div class="summary-item">
      <div class="summary-number healthy">{{ $json.healthy_count }}</div>
      <div class="summary-label">Healthy</div>
    </div>
    <div class="summary-item">
      <div class="summary-number problems">{{ $json.problem_count }}</div>
      <div class="summary-label">Need Attention</div>
    </div>
  </div>

  <div class="content">
    {{ $json.problem_count > 0 ? '<div class="section"><h2 class="section-title">⚠️ Repositories Needing Attention</h2><ul class="repo-list">' + $json.problem_repos.map(r => '<li class="repo-item ' + r.status + '"><div class="repo-name">' + r.repository + '<span class="repo-score score-' + r.status + '">' + r.health_score + '/100</span></div><div class="repo-details">📊 ' + r.stats.stars + ' stars • 🐛 ' + r.stats.open_issues + ' issues • 📅 ' + r.stats.days_since_update + ' days since update • 💻 ' + (r.stats.language || 'N/A') + '</div>' + (r.problems.length > 0 ? '<ul class="problem-list">' + r.problems.map(p => '<li>' + p + '</li>').join('') + '</ul>' : '') + '<div style="margin-top: 10px;"><a href="' + r.repo_url + '" class="btn">View Repo</a></div></li>').join('') + '</ul></div>' : '' }}

    <div class="claude-box">
      <h3>🧠 Claude AI Analysis</h3>
      <div class="claude-content">{{ $json.claude_analysis }}</div>
    </div>

    {{ $json.healthy_count > 0 ? '<div class="section"><h2 class="section-title">✅ Healthy Repositories</h2><ul class="repo-list">' + $json.healthy_repos.map(r => '<li class="repo-item"><div class="repo-name">' + r.repository + '<span class="repo-score score-healthy">' + r.health_score + '/100</span></div><div class="repo-details">📊 ' + r.stats.stars + ' stars • 🐛 ' + r.stats.open_issues + ' issues • 📅 ' + r.stats.days_since_update + ' days since update</div></li>').join('') + '</ul></div>' : '' }}

    <div style="text-align: center; margin: 30px 0;">
      <a href="https://github.com/orgs/Ai-Whisperers/repositories" class="btn">📂 View All Repositories</a>
    </div>
  </div>

  <div class="footer">
    <p><strong>🤖 Terry AI Agent</strong> | AI-Whisperers Infrastructure Monitoring</p>
    <p style="margin: 5px 0;">Powered by Claude 3 Haiku • n8n Automation</p>
    <p style="margin: 10px 0 0 0; font-style: italic;">"If you have to do it more than once, automate it."</p>
    <p style="margin: 10px 0 0 0; font-size: 11px; color: #999;">{{ $json.timestamp }}</p>
  </div>
</div>
</body>
</html>
